import json,html
from pathlib import Path
apps=json.loads(Path('apps.json').read_text(encoding='utf-8')); reviews=json.loads(Path('review.json').read_text(encoding='utf-8')); catalog=json.loads(Path('catalog_snapshot.json').read_text(encoding='utf-8')); catalog_by_name={x['app']:x for x in catalog['results']}
assert len(apps)==100 and len({a['name'] for a in apps})==100
for a in apps:
 d=json.loads(Path(f"data/{a['number']:03}.json").read_text(encoding='utf-8-sig'));a['results']=len(d['search_results']);a['fetched']=len(d['retrievals']);a['errors']=d['errors'];a['review']=[r for r in reviews if r['app']==a['name']];a['catalog']=catalog_by_name[a['name']];a['catalog_details']={};matches=a['catalog']['matches'];detail=Path('data/catalog')/(matches[0]['slug']+'.json') if matches else None;raw=json.loads(detail.read_text(encoding='utf-8')).get('text','') if detail and detail.exists() else '';a['catalog_details']={'purpose':raw.split('Latest version ',1)[-1].split(' ',1)[-1].split(' Copy page Authentication Details',1)[0] if ' Copy page Authentication Details' in raw else '', 'auth_config':raw.split('Authentication Details ',1)[-1].split(' Frequently Asked Questions',1)[0].split(' Tools (',1)[0] if 'Authentication Details ' in raw else ''};a['discovery']=json.loads(Path(f"data/discovery/{a['number']:03}.json").read_text(encoding='utf-8')) if Path(f"data/discovery/{a['number']:03}.json").exists() else {};a['claims']={r['field']:r['correction'] for r in a['review']}
Path('final_dataset.json').write_text(json.dumps(apps,ensure_ascii=False,indent=2),encoding='utf-8')
encoded=json.dumps(apps,ensure_ascii=False).replace('</','<\\/')
fetched=sum(a['fetched']>0 for a in apps)
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Integration research | Work in progress</title><style>
:root{--ink:#192e27;--paper:#f4f2e9;--lime:#c9f56b;--muted:#617168}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:Inter,system-ui,sans-serif;line-height:1.55}header{background:#173b2f;color:#f8f8ed;padding:24px max(5vw,24px) 80px}nav{display:flex;justify-content:space-between;gap:12px;font-size:12px;letter-spacing:.12em;text-transform:uppercase}nav a{color:inherit}main{max-width:1200px;margin:auto;padding:0 24px}h1{font-family:Georgia,serif;font-weight:400;font-size:clamp(42px,7vw,86px);line-height:1.02;max-width:950px;margin:80px 0 28px}h2{font:400 clamp(32px,4vw,48px)/1.1 Georgia,serif;margin:0 0 20px}.lead{font-size:19px;max-width:740px;color:#d5e3d8}.status{display:inline-block;color:#20382d;background:var(--lime);border-radius:30px;padding:6px 13px;font-size:12px;font-weight:700}.stats{display:grid;grid-template-columns:repeat(4,1fr);background:#fff;border:1px solid #ced9cc;margin-top:-40px}.stat{padding:28px;border-right:1px solid #d9e0d5}.stat strong{display:block;font:36px Georgia,serif}.stat small{color:var(--muted)}section{padding:80px 0;border-bottom:1px solid #cbd5c9}.eyebrow{font-size:12px;letter-spacing:.15em;font-weight:700;text-transform:uppercase;color:#52725a}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{background:#fff;padding:26px;border:1px solid #d7e0d4}.card h3{margin-top:0}.notice{background:#e8efdb;padding:22px;border-left:4px solid #658c38}.tools{display:flex;gap:12px;flex-wrap:wrap;margin:24px 0}input,select,button{font:inherit;padding:10px;border:1px solid #a5b5a5;background:white;color:var(--ink);border-radius:3px}input{min-width:260px}button{cursor:pointer}.tablewrap{overflow:auto}table{border-collapse:collapse;width:100%;background:white;font-size:14px}th,td{text-align:left;vertical-align:top;padding:14px;border-bottom:1px solid #e1e7de}th{font-size:12px;text-transform:uppercase}a{color:#215e40}header a{color:#e0f5ca}details{min-width:160px}footer{padding:50px 0;color:var(--muted)}@media(max-width:760px){.stats{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}header{padding-bottom:65px}h1{margin-top:55px}.stat{border-bottom:1px solid #d9e0d5}section{padding:56px 0}}@media(prefers-reduced-motion:reduce){*{animation:none!important;scroll-behavior:auto!important}}</style></head><body><header><nav><span>Product operations / Research notebook</span><a href="#evidence">Explore the 100 apps ↓</a></nav><h1>100 apps. Decisions still need evidence.</h1><p class="lead">An honest first pass at the Composio integration research assignment. Search ran across the assigned list; source-specific decisions and independent verification remain unfinished.</p><span class="status">WORK IN PROGRESS · NOT SUBMISSION READY</span></header><main><div class="stats"><div class="stat"><strong>100</strong><small>unique assigned apps</small></div><div class="stat"><strong>100</strong><small>searches completed</small></div><div class="stat"><strong>__FETCHED__ / 100</strong><small>at least one candidate page fetched; not verified coverage</small></div><div class="stat"><strong>Not measured</strong><small>first-pass accuracy; sample is incomplete</small></div></div><section><div class="eyebrow">01 / Decision status</div><h2>Do not turn search coverage into buildability.</h2><div class="grid"><article class="card"><h3>Engineering</h3><p>Review claim-specific authentication and endpoint docs before sizing an integration. Search matches alone do not establish a usable API.</p></article><article class="card"><h3>Product</h3><p>Separate test access from production permissions. Google Ads documents a production access application even when test access is available.</p></article><article class="card"><h3>Research</h3><p>The public Composio catalog lists 61 exact-name matches among the 100; 39 names need alias review. A Composio toolkit is a separate fact from a vendor MCP server.</p></article></div></section><section><div class="eyebrow">02 / Method</div><h2>Search → retrieve → abstain → review</h2><p>Two scripted search passes covered every app. The second pass searched within the assigned hint domain and retrieved candidates for 58 apps. A retrieved page is not necessarily relevant documentation or a verified claim. The extractor left every claim unknown because a search result alone cannot establish it. Eleven individual claims across ten categories have since been independently checked against official documentation; this is not the full six-field review required by the brief. This is AI-assisted documentation review, not a human review by the applicant.</p><div class="notice"><b>What this run cannot tell us:</b> which apps are buildable, the category breakdown of access gates, the most common blocker, or measured agent accuracy. First-pass abstentions are unresolved, not correct answers.</div></section><section><div class="eyebrow">03 / Evidence review</div><h2>Eleven claims, ten categories.</h2><div class="grid"><article class="card"><h3>Slack / authentication</h3><p>Agent: unknown → Docs: OAuth 2.0 and scoped tokens.</p><a href="https://docs.slack.dev/authentication/">Official authentication docs ↗</a></article><article class="card"><h3>Slack / MCP</h3><p>Agent: unknown → Docs: Slack operates an MCP server. This says nothing about a Composio toolkit.</p><a href="https://docs.slack.dev/ai/slack-mcp-server/">Official MCP docs ↗</a></article><article class="card"><h3>Google Ads / access</h3><p>Agent: unknown → Docs: test access is available after enabling the API; production access requires an application for an appropriate access level.</p><a href="https://developers.google.com/google-ads/api/docs/api-policy/access-levels">Official access docs ↗</a></article></div><p>GitHub’s <a href="https://docs.github.com/en/rest/using-the-rest-api/getting-started-with-the-rest-api">REST documentation</a> also establishes a documented REST surface. These are targeted examples, not a complete claim-by-claim review or an accuracy calculation. Additional checked claims appear in the table.</p></section><section id="evidence"><div class="eyebrow">04 / Research set</div><h2>The assigned 100.</h2><p>Every row needs further review. Candidate retrieval is not the same as verified evidence. Expand a row for review status.</p><div class="tools"><label>Search <input id="search" type="search" placeholder="App or category"></label><label>Category <select id="category"><option value="">All categories</option></select></label><button id="sort">Sort A–Z</button><button id="download">Export JSON</button></div><p id="count" aria-live="polite"></p><div class="tablewrap"><table><thead><tr><th>App</th><th>Category</th><th>Candidate retrieval</th><th>Composio catalog</th><th>Buildability</th><th>Details</th></tr></thead><tbody id="rows"></tbody></table></div></section><section><div class="eyebrow">05 / Limitations</div><h2>Work remaining</h2><p>Finish claim-level extraction with official sources, check catalog aliases, review all six required fields for a sample across all ten categories, score the same claims before and after correction, verify interactions on desktop and mobile, and publish a live page with a source repository. No real credentials were tested. This local page and its research log are a starting point, not a finished submission.</p></section><footer>Assignment research notebook · source snapshot and reproducibility instructions are in the project files.</footer></main><script>
const data=__DATA__;const rows=document.querySelector('#rows'),search=document.querySelector('#search'),category=document.querySelector('#category');let asc=true;const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));[...new Set(data.map(a=>a.category))].forEach(c=>{let o=document.createElement('option');o.value=o.textContent=c;category.append(o)});function render(){let q=search.value.toLowerCase(),list=data.filter(a=>(a.name+' '+a.category).toLowerCase().includes(q)&&(!category.value||a.category===category.value)).sort((a,b)=>asc?a.name.localeCompare(b.name):b.name.localeCompare(a.name));document.querySelector('#count').textContent=`${list.length} of ${data.length} apps shown`;rows.innerHTML=list.map(a=>`<tr><td><b>${esc(a.name)}</b></td><td>${esc(a.category)}</td><td>${a.fetched?'Candidate fetched':'No candidate fetched'}</td><td>${a.catalog.status==='listed'?`<a href="${esc(a.catalog.matches[0].url)}">Listed ↗</a>`:'Unknown (no exact match)'}</td><td>Unclear</td><td><details><summary>Research status</summary>${a.catalog_details.purpose?`<p>Composio description: ${esc(a.catalog_details.purpose)}</p>`:''}${a.catalog_details.auth_config?`<p>Composio auth configurations: ${esc(a.catalog_details.auth_config)}. Vendor methods may differ.</p>`:''}<p>${a.results} original search results. ${esc(a.errors.join('; ')||'Candidate needs claim review.')} Second pass: ${(a.discovery.fetches||[]).length} candidate pages; ${esc((a.discovery.errors||[]).join('; '))} ${(a.discovery.fetches||[]).filter(x=>/^https?:/.test(x.url)).map(x=>`<a href="${esc(x.url)}">Candidate page (HTTP ${x.status}) ↗</a>`).join(' ')}</p>${a.review.map(r=>`<p>${esc(r.field)}: ${esc(r.correction)} <a href="${esc(r.url)}">Official source ↗</a></p>`).join('')}</details></td></tr>`).join('')}search.addEventListener('input',render);category.addEventListener('change',render);document.querySelector('#sort').onclick=()=>{asc=!asc;document.querySelector('#sort').textContent=asc?'Sort A–Z':'Sort Z–A';render()};document.querySelector('#download').onclick=()=>{let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='research-status.json';a.click();URL.revokeObjectURL(a.href)};render();</script></body></html>'''
